INSERT INTO `productdivision` (`productDivisionID`, `name`, `description`) VALUES
  ('PD_000001', 'Beauté et Santé', 'Produiits cosmétiques pour maintenir, soigner ou modifier l\'état corporel '),
  ('PD_000002', 'Bijoux', 'Objet précieux utilisé comme parure sur le corps.'),
  ('PD_000003', 'Habillement', 'Assemblage pour recouvrir et protéger le pied; article pour servant à revètir le corps.'),
  ('PD_000004', 'Sacs', 'Contenant fait d\'une matière souple mise en double et assemblée sur les côtés et le fond, la partie supérieure étant seule ouverte.'),
  ('PD_000005', 'Fournitures', 'Meubles ou objets de rangement de maison'),
  ('PD_000006', 'Tissus', 'Matière souple et mince obtenue par l\'assemblage régulier de fils ou de fibres entrecroisés, soit par mailles avec un seul fil, soit par tissage avec plusieurs fils.'),
  ('PD_000007', 'Arts', 'Ensemble des ornements d\'architecture, peinture, sculpture, etc., employés pour embellir un édifice, un appartement, etc. Une oeuvre d\'art est un objet physique en deux ou trois dimensions qui remplit une fonction esthétique.'),
  ('PD_000008', 'Réligions et Funérailles', 'Produits à caractère réligieux ou utilisés dans les funérailles Africains');
INSERT INTO `productline` (`productLineID`, `productDivisionID`, `name`, `description`) VALUES
  ('PL_0000002', 'PD_000001', 'Cosmetiques', 'Une substance ou un mélange destiné à être mis en contact avec diverses parties superficielles du corps humain.'),
  ('PL_0000003', 'PD_000001', 'Santé', 'Une substance ou produit permettant de soigner ou de retablir la fonctionnalité d\'une partie du corps humain.'),
