  ('PL_0000007', 'PD_000002', 'Boutons de manchette', 'Un objet de type bijou utlisé pour fermer les manches de chemises.'),
  ('PL_0000008', 'PD_000002', 'Bracelets', 'Ornement ou bande d\'identifiction qui se porte principalement au bras, autour du poignet. '),
